/**
 * The colors 「設定」 offers for markers.
 *
 * Word's highlighter is not a free color picker: `font.highlightColor` snaps to
 * the nearest of the highlighter's own colors, so offering a full color wheel
 * would let the user choose a color the document never shows. These are picked
 * to land on distinct Word highlights, and every checklist default appears here
 * so a category's current color is always one of the options.
 */
export interface PaletteColor {
  /** Hex passed to `font.highlightColor`. */
  readonly value: string;
  readonly label: string;
}

export const HIGHLIGHT_PALETTE: readonly PaletteColor[] = Object.freeze([
  { value: "#FFFF00", label: "黄" },
  { value: "#FFE066", label: "うすい黄" },
  { value: "#FFD699", label: "クリーム" },
  { value: "#B6FF00", label: "黄緑" },
  { value: "#00FF00", label: "明るい緑" },
  { value: "#80FFFF", label: "水色" },
  { value: "#80DEEA", label: "シアン" },
  { value: "#00FFFF", label: "ターコイズ" },
  { value: "#8080FF", label: "青紫" },
  { value: "#FF80FF", label: "ピンク" },
  { value: "#FF00FF", label: "マゼンタ" },
  { value: "#FFA0A0", label: "サーモン" },
  { value: "#C0C0C0", label: "グレー" },
]);

/** Upper-case hex if the value is one this palette offers, otherwise null. */
export function paletteColor(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const hex = value.toUpperCase();
  return HIGHLIGHT_PALETTE.some((color) => color.value === hex) ? hex : null;
}

export function colorLabel(value: string): string {
  const hex = value.toUpperCase();
  return HIGHLIGHT_PALETTE.find((color) => color.value === hex)?.label ?? hex;
}
