/**
 * 1-(3) 文章の可読性に関すること — 黄緑マーカー.
 *
 * Covers the checklist items that a program can decide on its own: word choice
 * (漢字/かな, 冗長表現, カジュアル表現), sentence length, 多重修飾, 指示語, and
 * 表記のゆらぎ. The two structural items (段落の区切り, トピックセンテンス) need a
 * human and are deliberately not modelled here.
 */
import { CASUAL, KANJI_MEANING, KANJI_TO_KANA, VARIANT_GROUPS, VERBOSE } from "../dict.ts";
import type { DocumentRule, Finding, ParagraphRule } from "../types.ts";
import { finding } from "../types.ts";
import { escapeRegExp, matchAll, splitSentences } from "../text.ts";
import { arrowMessage, dictionaryRule } from "./dictRule.ts";

export const kanjiToKanaRule = dictionaryRule({
  id: "kanji-to-kana",
  category: "readability",
  title: "漢字で書くべきでない表現①（通例かな書き）",
  entries: KANJI_TO_KANA,
  message: arrowMessage("通例かな書きの語"),
});

export const kanjiMeaningRule = dictionaryRule({
  id: "kanji-meaning",
  category: "readability",
  title: "漢字で書くべきでない表現②（漢字とかなで意味が違う）",
  entries: KANJI_MEANING,
  message: arrowMessage("かな書きが適切か確認"),
});

export const verboseRule = dictionaryRule({
  id: "verbose-expression",
  category: "readability",
  title: "表現をもっと簡潔に",
  entries: VERBOSE,
  message: arrowMessage("より短い表現へ"),
});

export const casualRule = dictionaryRule({
  id: "casual-expression",
  category: "readability",
  title: "カジュアルすぎる表現",
  entries: CASUAL,
  message: arrowMessage("論文にそぐわない口語表現"),
});

// --- 長すぎる文 ------------------------------------------------------------
//
// 字数だけで決めていたときは、論文でごく普通の 150〜200 字の文まで指摘していた。
// 長さそのものは読みにくさではない。読み手が困るのは、**息継ぎがないこと**と、
// **1 文が抱える情報が多すぎること**の 2 つ。そこで長さは足切りに使い、その先を
// 構造で判断する。
//
// 読点の数そのものは 多重修飾 の担当なので、ここでは数えない。

/** 読点・括弧など、読み手が息を継げる場所。 */
const PAUSE = /[、，,；;：:（）()「」『』〔〕[\]]/u;

/** 区切りなしにこれ以上続くと、長さに関わらず読み下せない。 */
const BREATH_LIMIT = 60;

/** 目安のこの倍を超えたら、区切られていても 1 文に詰め込みすぎ。 */
const HARD_MULTIPLIER = 1.5;

/** 区切りのない最長区間の長さ. */
function longestRun(sentence: string): number {
  let longest = 0;
  let run = 0;
  for (const char of sentence) {
    if (PAUSE.test(char)) {
      run = 0;
      continue;
    }
    run += 1;
    if (run > longest) longest = run;
  }
  return longest;
}

/** 長すぎる文章があるので適宜分割が必要. */
export const longSentenceRule: ParagraphRule = {
  id: "long-sentence",
  category: "readability",
  title: "長すぎる文",
  kind: "paragraph",
  run(text, index, ctx): Finding[] {
    const limit = ctx.settings.maxSentenceLength;
    const found: Finding[] = [];
    for (const sentence of splitSentences(text)) {
      const body = sentence.text.trim();
      const length = body.length;
      if (length <= limit) continue;

      const run = longestRun(body);
      const reason =
        length > limit * HARD_MULTIPLIER
          ? `目安 ${limit} 字の ${HARD_MULTIPLIER} 倍を超えています`
          : run > BREATH_LIMIT
            ? `読点や括弧のない ${run} 字の続きがあります`
            : null;
      // 目安は超えているが、区切りがあって詰め込みすぎでもない文。論文では普通の長さ。
      if (reason === null) continue;

      found.push(
        finding(longSentenceRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: sentence.start,
          matched: sentence.text,
          message: `${length} 字の文です（目安 ${limit} 字）。${reason}。分割を検討してください。`,
        }),
      );
    }
    return found;
  },
};

// 「の」が3つ以上連続する連体修飾は、係り先が読み取りにくくなる典型。
const NO_CHAIN = /(?:[^\s、，。．]{1,8}の){3,}/gu;

/**
 * 「の」の連続 — 多重修飾から分けてある.
 *
 * 「試料の表面の酸化の状態」のような鎖は分解したほうが読みやすい一方、
 * 「有機薄膜太陽電池の変換効率の向上」のように専門用語が続くだけで 3 連続に
 * なる文も多い。指摘が多くなりすぎるので**既定では無効**（`catalog.ts`）。
 */
export const noChainRule: ParagraphRule = {
  id: "no-chain",
  category: "readability",
  title: "「の」の連続",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];
    for (const m of matchAll(NO_CHAIN, text)) {
      const chain = (m[0].match(/の/gu) ?? []).length;
      found.push(
        finding(noChainRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: m.index,
          matched: m[0],
          message: `「の」が ${chain} 連続しています。修飾関係を分解してください。`,
        }),
      );
    }
    return found;
  },
};

/** 多重修飾で文章が読みづらいので文の組み立て方の再検討が必要. */
export const multiModifierRule: ParagraphRule = {
  id: "multi-modifier",
  category: "readability",
  title: "多重修飾",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];

    for (const sentence of splitSentences(text)) {
      const commas = (sentence.text.match(/[、，]/gu) ?? []).length;
      if (commas < 4) continue;
      found.push(
        finding(multiModifierRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: sentence.start,
          matched: sentence.text,
          message: `読点が ${commas} 個ある文です。修飾が重なっていないか確認してください。`,
        }),
      );
    }

    return found;
  },
};

// Longest-first so 「このような」 is counted once, not as 「この」 plus 「ような」.
const DEMONSTRATIVE = /このような|そのような|これら|それら|この|その|これ|それ/gu;

/** 指示語の用法の問題（指し示す内容が自明でなくわかりづらい）. */
export const demonstrativeRule: ParagraphRule = {
  id: "demonstrative",
  category: "readability",
  title: "指示語の多用",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];
    for (const sentence of splitSentences(text)) {
      const hits = [...matchAll(DEMONSTRATIVE, sentence.text)];
      if (hits.length < 3) continue;
      found.push(
        finding(demonstrativeRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: sentence.start,
          matched: sentence.text,
          message: `指示語が ${hits.length} 個あります（${hits.map((h) => h[0]).join("、")}）。指す内容が自明か確認してください。`,
        }),
      );
    }
    return found;
  },
};

/**
 * Reports a spelling group only when the document actually mixes its members;
 * a document that consistently writes 「行なう」 is internally consistent and is
 * left alone.
 */
export const variantConsistencyRule: DocumentRule = {
  id: "notation-variance",
  category: "readability",
  title: "表記のゆらぎ",
  kind: "document",
  run(paragraphs): Finding[] {
    const found: Finding[] = [];

    for (const group of VARIANT_GROUPS) {
      const used = group.filter((form) =>
        paragraphs.some((p) => p.includes(form) && !overlapsLongerForm(p, form, group)),
      );
      if (used.length < 2) continue;

      // Flag every occurrence of the minority spellings so the author can jump
      // to each one; the most frequent spelling is treated as the house style.
      const counts = new Map(
        used.map((form) => [form, paragraphs.reduce((n, p) => n + countOccurrences(p, form, group), 0)]),
      );
      const preferred = [...counts.entries()].sort((a, b) => b[1] - a[1])[0]![0];

      for (const form of used) {
        if (form === preferred) continue;
        const pattern = new RegExp(escapeRegExp(form), "gu");
        paragraphs.forEach((p, index) => {
          for (const m of matchAll(pattern, p)) {
            if (overlapsLongerForm(p, form, group, m.index)) continue;
            found.push(
              finding(variantConsistencyRule, {
                severity: "confirm",
                paragraphIndex: index,
                start: m.index,
                matched: m[0],
                replacement: preferred,
                message: `表記ゆれ：「${form}」(${counts.get(form)}件) と「${preferred}」(${counts.get(preferred)}件) が混在しています。`,
              }),
            );
          }
        });
      }
    }

    return found;
  },
};

/**
 * Guards short group members that are prefixes of longer ones — "ユーザ" is a
 * substring of "ユーザー", so a document using only the long form must not look
 * like it mixes both.
 */
function overlapsLongerForm(
  text: string,
  form: string,
  group: readonly string[],
  at?: number,
): boolean {
  const longer = group.filter((other) => other !== form && other.startsWith(form));
  if (longer.length === 0) return false;
  if (at !== undefined) return longer.some((other) => text.startsWith(other, at));
  // No position given: true only when *every* occurrence is part of a longer form.
  const pattern = new RegExp(escapeRegExp(form), "gu");
  for (const m of matchAll(pattern, text)) {
    if (!longer.some((other) => text.startsWith(other, m.index))) return false;
  }
  return true;
}

function countOccurrences(text: string, form: string, group: readonly string[]): number {
  const pattern = new RegExp(escapeRegExp(form), "gu");
  let n = 0;
  for (const m of matchAll(pattern, text)) {
    if (!overlapsLongerForm(text, form, group, m.index)) n += 1;
  }
  return n;
}

/**
 * 句読点の統一. Japanese scientific writing picks either 。、 or ．， and sticks
 * to it; the checklist itself uses ．，. Mixing the two is a formatting error
 * rather than a matter of taste, so the minority style is flagged everywhere.
 */
export const punctuationConsistencyRule: DocumentRule = {
  id: "punctuation-consistency",
  category: "readability",
  title: "句読点の統一（。、 と ．，）",
  kind: "document",
  run(paragraphs, ctx): Finding[] {
    if (!ctx.isJapanese) return [];
    const found: Finding[] = [];

    for (const [a, b, name] of [
      ["。", "．", "句点"],
      ["、", "，", "読点"],
    ] as const) {
      const countA = paragraphs.reduce((n, p) => n + occurrences(p, a), 0);
      const countB = paragraphs.reduce((n, p) => n + occurrences(p, b), 0);
      if (countA === 0 || countB === 0) continue;

      const minority = countA < countB ? a : b;
      const majority = countA < countB ? b : a;
      paragraphs.forEach((p, index) => {
        for (const m of matchAll(new RegExp(escapeRegExp(minority), "gu"), p)) {
          found.push(
            finding(punctuationConsistencyRule, {
              severity: "fix",
              paragraphIndex: index,
              start: m.index,
              matched: minority,
              replacement: majority,
              message: `${name}が混在しています（「${a}」${countA}件／「${b}」${countB}件）。文書内で統一してください。`,
            }),
          );
        }
      });
    }

    return found;
  },
};

/** 常体・敬体の混在。論文は「である」体に揃える。 */
export const politenessConsistencyRule: DocumentRule = {
  id: "politeness-consistency",
  category: "readability",
  title: "です・ます体の混在",
  kind: "document",
  run(paragraphs, ctx): Finding[] {
    if (!ctx.isJapanese) return [];
    const polite = /(で(す|した)|ます|ました|ません)(?=[。．！？!?]|$)/gu;
    const found: Finding[] = [];
    const plain = paragraphs.reduce(
      (n, p) => n + occurrences(p, "である") + occurrences(p, "した。") + occurrences(p, "した．"),
      0,
    );
    if (plain === 0) return [];

    paragraphs.forEach((p, index) => {
      for (const m of matchAll(polite, p)) {
        found.push(
          finding(politenessConsistencyRule, {
            severity: "confirm",
            paragraphIndex: index,
            start: m.index,
            matched: m[0],
            message: "常体（である体）の文書に敬体が混ざっています。",
          }),
        );
      }
    });
    return found;
  },
};

function occurrences(text: string, needle: string): number {
  let n = 0;
  let from = 0;
  for (;;) {
    const at = text.indexOf(needle, from);
    if (at === -1) return n;
    n += 1;
    from = at + needle.length;
  }
}

export const READABILITY_RULES = [
  kanjiToKanaRule,
  kanjiMeaningRule,
  verboseRule,
  casualRule,
  longSentenceRule,
  noChainRule,
  multiModifierRule,
  demonstrativeRule,
  variantConsistencyRule,
  punctuationConsistencyRule,
  politenessConsistencyRule,
];
