/* global Word */
/**
 * 「この文書はどのフォントで書かれているか」と「まとめて置き換える」.
 *
 * Office.js has no run-level API: `paragraph.font.name` answers with the
 * paragraph's font, or with an empty string when the paragraph mixes several —
 * which is exactly the case a manuscript is in, with 和文 in ＭＳ明朝 and the
 * Latin in Times New Roman inside one sentence.
 *
 * So the scan is three-tier, each tier applied only to what the one before it
 * could not answer. Every paragraph is asked first; the ones that answer 「mixed」
 * are broken into word ranges with `getTextRanges`; the words that are *still*
 * mixed — which in 和文 is most of them, since there are no spaces to split on —
 * are searched for their Latin runs. That keeps the cost proportional to the
 * messy parts instead of paying one range per word across the whole document: a
 * 20-page draft would otherwise cost eight thousand ranges to answer a question
 * about a handful of fonts.
 *
 * Replacement walks the same units, so what the list shows and what the button
 * changes are the same set of ranges.
 */
import { isJapaneseFontName, normalizeTextColor, textColorLabel } from "../core/fonts.ts";

/** One font the document actually uses. */
export interface FontUsage {
  readonly name: string;
  /** How many ranges carry it — paragraphs, or words inside mixed paragraphs. */
  readonly ranges: number;
  /** Characters in those ranges, excluding spaces and paragraph marks. */
  readonly characters: number;
  /** A short piece of text set in it, so the user can tell what it is. */
  readonly sample: string;
  /** True when the name looks like a Japanese font. */
  readonly japanese: boolean;
}

/** Character formatting that can be surveyed, replaced, and highlighted. */
export type CharacterStyle = "bold" | "italic" | "superscript" | "subscript";

export interface CharacterStyleUsage {
  readonly style: CharacterStyle;
  readonly label: string;
  /** Number of characters carrying this formatting. */
  readonly characters: number;
}

/** One font size the document actually uses, in points. */
export interface SizeUsage {
  readonly size: number;
  readonly characters: number;
}

/** One text color the document actually uses. */
export interface ColorUsage {
  /** Upper-case `#RRGGBB`, or Word's own word for「色の指定なし」. */
  readonly color: string;
  readonly label: string;
  readonly characters: number;
}

/**
 * 「文字」が 1 文字ずつ数えるもの。
 *
 * 書体・文字サイズ・文字色を**一度の走査でまとめて**返す。3 つに分けると
 * 1 文字ずつの range を 3 回作ることになり、この画面でいちばん重い処理が
 * 3 倍になる（下の `styleUnits` の注記を参照）。
 */
export interface TextAppearance {
  readonly styles: readonly CharacterStyleUsage[];
  readonly sizes: readonly SizeUsage[];
  readonly colors: readonly ColorUsage[];
}

export const CHARACTER_STYLES: readonly { readonly style: CharacterStyle; readonly label: string }[] = Object.freeze([
  { style: "bold", label: "太字" },
  { style: "italic", label: "斜体" },
  { style: "superscript", label: "上付き" },
  { style: "subscript", label: "下付き" },
]);

/** Word splits a range at these marks; a space gives word-sized pieces. */
const WORD_DELIMITERS = [" "];

/**
 * A run of Latin letters and digits, as a Word wildcard search.
 *
 * The third tier, and the one that matters for a Japanese manuscript. Splitting
 * on spaces assumes words have spaces around them, which 和文 does not: a whole
 * clause like 「1に示す装置を用い、25–30」 comes back as one "word", mixes scripts,
 * and so answers 「mixed」 all over again. Everything Latin then hides inside it.
 *
 * Searching for the Latin runs asks the question directly instead, and only of
 * the pieces that are still ambiguous.
 */
const LATIN_RUN = "[A-Za-z0-9]{1,}";

/**
 * The same idea for 和文, so a mixed piece is asked about from both sides.
 *
 * Whether this adds anything depends on the manuscript. Office.js exposes one
 * `font.name` per range, while DOCX stores an ascii font and an eastAsia font
 * side by side — so a run whose Latin is Calibri and whose 和文 is 游明朝 can only
 * answer with one of them. Asking a 和文-only range improves the odds of getting
 * the other, and costs one search on pieces that were going to be dropped.
 *
 * It does not make the pair readable in general. A document that leaves its
 * fonts to the theme (`asciiTheme="minorHAnsi"`) has no name stored anywhere for
 * this to find, which is why 「Calibri (Body)」 and 「Yu Mincho Regular」 — Word's
 * own labels for the theme fonts — need not appear here at all.
 */
const CJK_RUN = "[ぁ-んァ-ヶ一-龥]{1,}";
const WILDCARD: Word.SearchOptions | object = { matchWildcards: true };

interface Unit {
  readonly font: Word.Font;
  readonly text: string;
}

/**
 * Every range whose font can be read, with the text it covers.
 *
 * Two syncs: one to learn which paragraphs are mixed, one to read the fonts of
 * the pieces those were split into.
 */
async function fontUnits(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
): Promise<Unit[]> {
  for (const paragraph of paragraphs) {
    paragraph.load("text");
    paragraph.font.load("name");
  }
  await context.sync();

  const units: Unit[] = [];
  const splits: Array<{ text: string; ranges: Word.RangeCollection }> = [];

  for (const paragraph of paragraphs) {
    const text = paragraph.text ?? "";
    if (text.trim().length === 0) continue;
    if (paragraph.font.name) {
      units.push({ font: paragraph.font, text });
      continue;
    }
    // Mixed paragraph: ask for the pieces. `getTextRanges` is WordApi 1.3; a
    // host without it simply contributes nothing rather than failing the scan.
    if (typeof paragraph.getTextRanges !== "function") continue;
    const ranges = paragraph.getTextRanges(WORD_DELIMITERS, false);
    ranges.load("items/text");
    splits.push({ text, ranges });
  }

  if (splits.length === 0) return units;
  await context.sync();

  const pieces: Array<{ range: Word.Range; text: string }> = [];
  for (const split of splits) {
    for (const range of split.ranges.items) {
      range.font.load("name");
      pieces.push({ range, text: range.text ?? split.text });
    }
  }
  await context.sync();

  // Third tier: pieces that are *still* mixed. Dropping them, which is what this
  // did until 2026-07-29, is why 「フォントを置換」 listed the 和文 fonts of a
  // manuscript and none of the Latin ones — the Latin was never in a piece of
  // its own to be asked about.
  const runs: Word.RangeCollection[] = [];
  for (const piece of pieces) {
    if (piece.range.font.name) {
      units.push({ font: piece.range.font, text: piece.text });
      continue;
    }
    if (typeof piece.range.search !== "function") continue;
    for (const pattern of [LATIN_RUN, CJK_RUN]) {
      const results = piece.range.search(pattern, WILDCARD as Word.SearchOptions);
      results.load("items/text");
      runs.push(results);
    }
  }

  if (runs.length === 0) return units;
  await context.sync();

  for (const results of runs) {
    for (const range of results.items) {
      range.font.load("name");
      units.push({ font: range.font, text: range.text ?? "" });
    }
  }
  await context.sync();

  return units;
}

/**
 * Formatting is often mixed inside a single word.  Word does not expose runs,
 * so this intentionally asks one wildcard range per visible character.  It is
 * used only from the on-demand 「文字」 view, where correctness is preferable to
 * treating a partially bold Japanese sentence as an all-or-nothing paragraph.
 */
async function styleUnits(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
): Promise<Unit[]> {
  const collections: Word.RangeCollection[] = [];
  for (const paragraph of paragraphs) {
    const ranges = paragraph.search("?", WILDCARD as Word.SearchOptions);
    ranges.load("items/text");
    collections.push(ranges);
  }
  await context.sync();

  const units: Unit[] = [];
  for (const ranges of collections) {
    for (const range of ranges.items) {
      // サイズと色をここで一緒に読む。range を作り直さないので往復は増えず、
      // 増えるのは 1 文字あたりのプロパティ 2 つぶんだけ。
      range.font.load("bold, italic, superscript, subscript, size, color");
      units.push({ font: range.font, text: range.text ?? "" });
    }
  }
  await context.sync();
  return units;
}

function hasStyle(font: Word.Font, style: CharacterStyle): boolean {
  return font[style] === true;
}

/** The fonts in use, most-used first. */
export async function scanFonts(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
): Promise<FontUsage[]> {
  const units = await fontUnits(context, paragraphs);

  const counts = new Map<string, { ranges: number; characters: number; sample: string }>();
  for (const unit of units) {
    const name = unit.font.name;
    if (!name) continue;
    const characters = unit.text.replace(/\s/gu, "").length;
    const existing = counts.get(name);
    if (existing) {
      existing.ranges += 1;
      existing.characters += characters;
      continue;
    }
    counts.set(name, { ranges: 1, characters, sample: unit.text.trim().slice(0, 24) });
  }

  return [...counts.entries()]
    .map(([name, info]) => ({ name, ...info, japanese: isJapaneseFontName(name) }))
    .sort((a, b) => b.ranges - a.ranges || a.name.localeCompare(b.name));
}

/** The character formatting, sizes and colors actually present in the document. */
export async function scanTextAppearance(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
): Promise<TextAppearance> {
  const units = await styleUnits(context, paragraphs);

  const styles = CHARACTER_STYLES
    .map(({ style, label }) => ({
      style,
      label,
      characters: units.filter((unit) => hasStyle(unit.font, style)).length,
    }))
    .filter((usage) => usage.characters > 0);

  // 1 unit = 1 文字 なので、数えるのは出現回数そのもの。
  const sizeCounts = new Map<number, number>();
  const colorCounts = new Map<string, number>();
  for (const unit of units) {
    const size = unit.font.size;
    if (typeof size === "number" && Number.isFinite(size) && size > 0) {
      sizeCounts.set(size, (sizeCounts.get(size) ?? 0) + 1);
    }
    const color = normalizeTextColor(unit.font.color);
    if (color !== null) colorCounts.set(color, (colorCounts.get(color) ?? 0) + 1);
  }

  const sizes = [...sizeCounts.entries()]
    .map(([size, characters]) => ({ size, characters }))
    .sort((a, b) => b.characters - a.characters || a.size - b.size);

  const colors = [...colorCounts.entries()]
    .map(([color, characters]) => ({ color, label: textColorLabel(color), characters }))
    .sort((a, b) => b.characters - a.characters || a.color.localeCompare(b.color));

  return { styles, sizes, colors };
}

/** Replaces one character formatting property with another (or normal text). */
export async function replaceCharacterStyle(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  from: CharacterStyle,
  to: CharacterStyle | "normal",
): Promise<number> {
  if (from === to) return 0;
  const units = await styleUnits(context, paragraphs);
  let changed = 0;
  for (const unit of units) {
    if (!hasStyle(unit.font, from)) continue;
    unit.font[from] = false;
    if (to !== "normal") unit.font[to] = true;
    changed += 1;
  }
  if (changed > 0) await context.sync();
  return changed;
}

/** Highlights every character with the requested formatting. */
export async function highlightCharacterStyle(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  style: CharacterStyle,
  color: string,
): Promise<number> {
  const units = await styleUnits(context, paragraphs);
  let highlighted = 0;
  for (const unit of units) {
    if (!hasStyle(unit.font, style)) continue;
    unit.font.highlightColor = color;
    highlighted += 1;
  }
  if (highlighted > 0) await context.sync();
  return highlighted;
}

/**
 * Sets every range currently in `from` to `to`. Returns how many were changed.
 *
 * The document is re-scanned rather than reusing the list's ranges: the list may
 * be minutes old, and writing a font onto a range that has since been edited is
 * the kind of mistake that is invisible until the figure captions come out wrong.
 */
export async function replaceFont(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  from: string,
  to: string,
): Promise<number> {
  if (from === to || from.length === 0 || to.length === 0) return 0;
  const units = await fontUnits(context, paragraphs);

  let changed = 0;
  for (const unit of units) {
    if (unit.font.name !== from) continue;
    unit.font.name = to;
    changed += 1;
  }
  if (changed > 0) await context.sync();
  return changed;
}

/** Highlights every range currently set in `name`, returning how many were found. */
export async function highlightFont(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  name: string,
  color: string,
): Promise<number> {
  if (name.length === 0) return 0;
  const units = await fontUnits(context, paragraphs);

  let highlighted = 0;
  for (const unit of units) {
    if (unit.font.name !== name) continue;
    unit.font.highlightColor = color;
    highlighted += 1;
  }
  if (highlighted > 0) await context.sync();
  return highlighted;
}

/** Removes only the recorded add-in colors from the corresponding fonts. */
export async function clearFontHighlights(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  highlights: ReadonlyMap<string, ReadonlySet<string>>,
): Promise<number> {
  if (highlights.size === 0) return 0;
  const units = await fontUnits(context, paragraphs);
  const targets = units.filter((unit) => highlights.has(unit.font.name ?? ""));
  for (const unit of targets) unit.font.load("highlightColor");
  if (targets.length > 0) await context.sync();

  const normal = (value: unknown): string =>
    typeof value === "string" ? value.replace(/^#/u, "").toUpperCase() : "";
  // Word sometimes returns a palette name in place of the requested hex color.
  const aliases: Readonly<Record<string, readonly string[]>> = {
    "FFFF00": ["YELLOW"], "B6FF00": ["BRIGHTGREEN"], "00FF00": ["GREEN"],
    "80FFFF": ["CYAN", "TURQUOISE"], "80DEEA": ["CYAN", "TURQUOISE"],
    "00FFFF": ["CYAN", "TURQUOISE"], "8080FF": ["BLUE"], "FF80FF": ["PINK"],
    "FF00FF": ["MAGENTA"], "FFA0A0": ["RED"], "C0C0C0": ["GRAY"],
  };
  let cleared = 0;
  for (const unit of targets) {
    const colors = highlights.get(unit.font.name ?? "")!;
    const accepted = new Set([...colors].flatMap((color) => [normal(color), ...(aliases[normal(color)] ?? [])]));
    if (!accepted.has(normal(unit.font.highlightColor))) continue;
    unit.font.highlightColor = null as unknown as string;
    cleared += 1;
  }
  if (cleared > 0) await context.sync();
  return cleared;
}

/** Removes recorded add-in highlights from characters with the given formatting. */
export async function clearCharacterStyleHighlights(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  highlights: ReadonlyMap<CharacterStyle, ReadonlySet<string>>,
): Promise<number> {
  if (highlights.size === 0) return 0;
  const units = (await styleUnits(context, paragraphs)).filter((unit) =>
    [...highlights.keys()].some((style) => hasStyle(unit.font, style)),
  );
  for (const unit of units) unit.font.load("highlightColor");
  if (units.length > 0) await context.sync();

  const normal = (value: unknown): string =>
    typeof value === "string" ? value.replace(/^#/u, "").toUpperCase() : "";
  const aliases: Readonly<Record<string, readonly string[]>> = {
    "FFFF00": ["YELLOW"], "B6FF00": ["BRIGHTGREEN"], "00FF00": ["GREEN"],
    "80FFFF": ["CYAN", "TURQUOISE"], "80DEEA": ["CYAN", "TURQUOISE"],
    "00FFFF": ["CYAN", "TURQUOISE"], "8080FF": ["BLUE"], "FF80FF": ["PINK"],
    "FF00FF": ["MAGENTA"], "FFA0A0": ["RED"], "C0C0C0": ["GRAY"],
  };
  let cleared = 0;
  for (const unit of units) {
    const colors = [...highlights.entries()]
      .filter(([style]) => hasStyle(unit.font, style))
      .flatMap(([, values]) => [...values]);
    const accepted = new Set(colors.flatMap((color) => [normal(color), ...(aliases[normal(color)] ?? [])]));
    if (!accepted.has(normal(unit.font.highlightColor))) continue;
    unit.font.highlightColor = null as unknown as string;
    cleared += 1;
  }
  if (cleared > 0) await context.sync();
  return cleared;
}
