/**
 * Shared vocabulary for the review engine.
 *
 * Everything here is Office-independent. A rule sees plain paragraph text and
 * returns `Finding`s with character offsets; the Office layer turns an offset
 * range into a `Word.Range` to highlight, select, or replace.
 */

/**
 * Top-level checklist sections, mirroring 添削チェックリスト. The marker colors
 * are the ones the checklist itself assigns, so a document reviewed by this
 * add-in is color-compatible with one reviewed by hand.
 */
export type Category = "structure" | "science" | "readability" | "format" | "figure" | "reference";

export interface CategoryInfo {
  readonly id: Category;
  /** Section label as it appears in the checklist. */
  readonly label: string;
  /** Two-or-three character name, for places too narrow for `label` (tabs). */
  readonly short: string;
  /** Word highlight color name accepted by `font.highlightColor`. */
  readonly highlight: string;
  /** CSS color for the task-pane swatch. */
  readonly swatch: string;
  /** Checklist's own name for the marker, shown in the UI. */
  readonly markerName: string;
}

