/**
 * How much the tool trusts its own judgement.
 *
 * - `fix`     — deterministic; safe to apply in bulk.
 * - `confirm` — the pattern is real but the right edit depends on context.
 * - `note`    — informational only, there is nothing to replace.
 */
export type Severity = "fix" | "confirm" | "note";

/** One flagged span of text. */
export interface Finding {
  /** Stable rule identifier, e.g. "kanji-to-kana". */
  readonly ruleId: string;
  readonly category: Category;
  readonly severity: Severity;
  /** Index into the paragraph array the engine was given. */
  readonly paragraphIndex: number;
  /** UTF-16 offsets within that paragraph. `end` is exclusive. */
  readonly start: number;
  readonly end: number;
  /** The exact text between `start` and `end`; used to locate the range in Word. */
  readonly matched: string;
  /** Replacement for `matched`, when the rule can propose one. */
  readonly replacement?: string;
  /** Short Japanese explanation shown in the task pane. */
  readonly message: string;
}

/** A rule that looks at one paragraph at a time. */
export interface ParagraphRule {
  readonly id: string;
  readonly category: Category;
  /** Human-readable rule name for the task pane's rule toggles. */
  readonly title: string;
  readonly kind: "paragraph";
  run(text: string, index: number, ctx: DocumentContext): Finding[];
}

/** A rule that needs to see the whole document (consistency, cross-references). */
export interface DocumentRule {
  readonly id: string;
  readonly category: Category;
  readonly title: string;
  readonly kind: "document";
  run(paragraphs: readonly string[], ctx: DocumentContext): Finding[];
}

export type Rule = ParagraphRule | DocumentRule;

/** Knobs that change how strict some rules are. */
export interface RuleSettings {
  /** Sentences longer than this many characters are flagged. */
  readonly maxSentenceLength: number;
  /** Whether the document is written in Japanese (affects citation placement). */
  readonly documentLanguage: "ja" | "en" | "auto";
}

export const DEFAULT_SETTINGS: RuleSettings = Object.freeze({
  // 100 字では論文でごく普通の文まで拾っていた。長さは足切りで、読みにくさの
  // 判断は long-sentence の構造チェックが受け持つ。
  maxSentenceLength: 200,
  documentLanguage: "auto",
});

/** Facts about the document that individual rules can consult. */
export interface DocumentContext {
  readonly settings: RuleSettings;
  /** True when the document is predominantly Japanese. */
  readonly isJapanese: boolean;
  /**
   * Dictionary entries the user has switched off, keyed by `entryKey()`.
   * A rule built from a word list consults this before reporting an entry.
   */
  readonly disabledEntries: ReadonlySet<string>;
  /**
   * 「数字＋英小文字」 tokens the document uses as compound numbers (18d, 1a).
   * Built by `compoundLabels()`; a rule that would otherwise read the letter as
   * a unit consults this first.
   */
  readonly compoundLabels: ReadonlySet<string>;
  /**
   * Word's automatic paragraph numbers, empty outside Word. A rule that looks
   * for the bibliography passes these on: a list numbered by Word carries its
   * numbers in the layout, not in the text.
   */
  readonly listNumbers: readonly (number | undefined)[];
}

/** Convenience constructor so rules stay terse. */
export function finding(
  rule: { id: string; category: Category },
  args: {
    severity: Severity;
    paragraphIndex: number;
    start: number;
    matched: string;
    message: string;
    replacement?: string;
  },
): Finding {
  return {
    ruleId: rule.id,
    category: rule.category,
    severity: args.severity,
    paragraphIndex: args.paragraphIndex,
    start: args.start,
    end: args.start + args.matched.length,
    matched: args.matched,
    ...(args.replacement === undefined ? {} : { replacement: args.replacement }),
    message: args.message,
  };
}
